      "ja": "\u9078\u629E\u80A2\u306E\u8B58\u5225\u5B50\u304C\u7121\u52B9\u3067\u3059\u3002",
      "ko": "\uC635\uC158 \uC2DD\uBCC4\uC790\uAC00 \uC720\uD6A8\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."
