    uk: { obeys: "\u0414\u043E\u0442\u0440\u0438\u043C\u0443\u0454\u0442\u044C\u0441\u044F", bends: "\u0417\u0433\u0438\u043D\u0430\u0454\u0442\u044C\u0441\u044F", breaks: "\u041F\u043E\u0440\u0443\u0448\u0443\u0454\u0442\u044C\u0441\u044F", establishes: "\u0412\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u044E\u0454\u0442\u044C\u0441\u044F", raise: "\u0417\u0440\u043E\u0441\u0442\u0430\u0454", turn: "\u041F\u043E\u0432\u0435\u0440\u0442\u0430\u0454", ease: "\u0421\u043B\u0430\u0431\u0448\u0430\u0454", resolve: "\u0417\u0430\u0432\u0435\u0440\u0448\u0443\u0454\u0442\u044C\u0441\u044F", step: "\u041F\u0440\u043E\u0441\u0443\u0432\u0430\u0454\u0442\u044C\u0441\u044F" },
